import { componentCatalog, type ComponentMetadata } from "../catalog/componentCatalog";
import { NormalizedData } from "../data/normalizeData";
import { designPresetPrompt } from "../design/stylePresets";
import { createFieldAliasRegistry } from "../fields/fieldAliasRegistry";
import { fieldManifestForPrompt } from "./fieldManifestForPrompt";
import { AiPromptSettings } from "./aiPromptSettings";
import { patternRegistry } from "../schema/patternRegistry";
import { v2CommonComponentProperties, v2ComponentPropertiesByType, v2RequiredPropertiesByType } from "../schema/validateV2Schema";

export interface PromptCompositionContext { width?:number;height?:number;currentSpecification?:string;diagnostics?:unknown[];selectedComponentId?:string;selectedComponentType?:string;selectedComponentTitle?:string;selectedComponentPath?:string;insertionTargetId?:string;insertionTargetType?:string;insertionTargetPath?:string;insertionPosition?:"before"|"after"|"inside";insertionContainerPath?:string;insertionRootContainer?:"components"|"toolbar"|"leftPanel"|"rightPanel";budget?:number; }
export interface ComposedPrompt { prompt:string;includedModules:string[];excludedModules:string[];approximateTokens:number;warnings:string[];fieldAliases:string[]; }
type Module={id:string;include:boolean;content:string};
const contract=`Use HyperPBI schema version 2.0. Return one complete JSON object with this root shape: {"version":"2.0","app":{"designSystem":"enterprise-light"},"data":{"datasets":{}},"definitions":{},"components":[]}.
Every component has a unique stable id. Components may reference one logical dataset with dataset. Components without dataset use the base Power BI data view.`;
const datasetLanguage=`Logical datasets are declared at data.datasets. Each definition requires source, which is "powerbi" or another listed dataset. After source resolution, runtime evaluation and static schema propagation use this deterministic order: filter, derive, rename, select, groupBy/metrics, distinct, sort, limit. Metric ops: sum, avg, min, max, count, distinctCount, first. Derive expressions use the safe calculation DSL only. A component sees only its selected dataset output. Dataset-derived fields and metrics cannot directly filter the Power BI model; source-row lineage may still support identity selection. No SQL, joins, functions, or network sources.`;
const security=`Security: no JavaScript, functions, eval, event-handler attributes, script tags, credentials, dynamic imports, unsafe iframe/object, or network datasets. HTML is sanitized, CSS is scoped/allowlisted, URLs and ArcGIS hosts remain subject to HyperPBI policy.`;
const output=`OUTPUT CONTRACT:
- Allowed operations are declarative dashboard creation or the explicitly requested strict change-package operation.
- Return one JSON object only.
- No Markdown fences, comments, explanations, or alternate versions.
- Use only listed field aliases, datasets, patterns, component types, properties, actions, and design tokens.
- Do not invent fields or business logic.
- Preserve stable IDs when a component remains.
- Any component type, property, action, dataset operation, pattern, field alias, or design token not listed in this prompt is invalid.`;

function relevantTypes(settings:AiPromptSettings,svgRequested=false):string[]{const types=new Set(["grid","section","card","kpi","metricGrid","text","emptyState"]);if(settings.tableRequired){types.add("table");types.add("detailPanel");}if(settings.chartsRequired)["lineChart","barChart","horizontalBarChart","areaChart","comboChart"].forEach(type=>types.add(type));if(settings.controlsRequired)["searchBox","select","multiSelect","dateRange","button"].forEach(type=>types.add(type));if(settings.mapRequired)types.add("map");if(settings.detailPanelRequired){types.add("offcanvas");types.add("detailPanel");}if(settings.components.includes("Advanced ECharts"))types.add("advancedChart");if(svgRequested)types.add("svg");return Array.from(types);}
function componentModule(types:string[],settings:AiPromptSettings):string{return types.map(type=>componentCatalog.find(component=>component.type===type)).filter((item):item is ComponentMetadata=>item!==undefined&&item.maturity!=="deprecated"&&(item.maturity!=="experimental"||settings.components.includes("Advanced ECharts"))&&(item.maturity!=="beta"||settings.complexity==="advanced"||item.type==="map"&&settings.mapRequired||item.type==="offcanvas"&&settings.detailPanelRequired)).map(item=>{const properties=Array.from(new Set([...v2CommonComponentProperties,...(v2ComponentPropertiesByType[item.type]??[])])).sort();const required=["type","id",...(v2RequiredPropertiesByType[item.type]??[])];return`${item.type} [${item.maturity}, ${item.complexity}]: ${item.useWhen}. Required: ${required.join(", ")}. Allowed properties: ${properties.join(", ")}.`;}).join("\n");}
function recommendedPatterns(data:NormalizedData):string[]{const registry=createFieldAliasRegistry(data);const roles=new Set(registry.entries.map(entry=>entry.semanticRole));const result:string[]=[];if(registry.entries.filter(entry=>["measure","currency","percentage"].includes(entry.semanticRole)).length>1)result.push("kpi-row");if((roles.has("date")||roles.has("datetime"))&&[...roles].some(role=>["measure","currency","percentage"].includes(role)))result.push("trend-and-breakdown");if(roles.has("identifier"))result.push("record-explorer");if(roles.has("geometry")||(roles.has("latitude")&&roles.has("longitude")))result.push("map-and-details");return result;}

export function composeAiPrompt(data:NormalizedData,settings:AiPromptSettings,context:PromptCompositionContext={}):ComposedPrompt{
    if(settings.job==="redesign-section"&&!context.selectedComponentId)throw new Error("Select a component before generating a redesign-section prompt.");if(settings.job==="add-section"&&!context.insertionTargetId&&!context.insertionRootContainer)throw new Error("Choose an insertion target or root destination before generating an add-section prompt.");
    const fields=fieldManifestForPrompt(data,settings.selectedFields,settings.privacyMode,settings.aliasOverrides) as Array<{alias:string;semanticRole:string}>;const intentText=[settings.goal,settings.requiredSections,settings.decisions,settings.importantKpis,...settings.components].join(" ");const svgRequested=/\b(svg|animat(?:e|ed|ion)|illustration|infographic|process flow|diagram|custom card|pictorial|custom gauge|progress animation|asset schematic|pipeline|flowing|moving marker|fish)\b/i.test(intentText);const types=relevantTypes(settings,svgRequested);const patterns=recommendedPatterns(data);const improvement=settings.job==="improve";const repair=settings.job==="repair";const map=settings.mapRequired;const advanced=settings.complexity==="advanced";const modules:Module[]=[
        {id:"root-contract",include:true,content:contract},
        {id:"field-manifest",include:true,content:`AVAILABLE FIELD ALIASES:\n${JSON.stringify(fields,null,2)}`},
        {id:"datasets",include:settings.calculationsRequired||/group|aggregate|dataset|derive/i.test(settings.goal+settings.requiredSections),content:datasetLanguage},
        {id:"patterns",include:true,content:`APPLICATION PATTERNS AVAILABLE:\n${patterns.map(id=>`${id}: required ${patternRegistry[id].required.join(", ")}; optional ${patternRegistry[id].optional.join(", ")}; example ${JSON.stringify(patternRegistry[id].example)}`).join("\n")||"No pattern is automatically recommended; first-class components remain available."}`},
        {id:"components",include:true,content:`COMPONENTS AVAILABLE:\n${componentModule(types,settings)}`},
        {id:"design-system",include:true,content:`DESIGN SYSTEM:\n${designPresetPrompt(settings.stylePreset||settings.designStyle)}\nUse semantic variant, intent, density, and emphasis values before custom CSS.`},
        {id:"interactions",include:true,content:`INTERACTIONS: ${settings.interactionExpectations}. internalMode is none, highlight, or filter. externalMode is none, auto, selection, or filter. External filters require a supplied model-column alias.`},
        {id:"maps",include:map,content:"MAP RULES: use the map component and existing bound latitude/longitude/geometry aliases. Respect feature limits and public-service host policy. Do not add secured services or credentials."},
        {id:"tables",include:settings.tableRequired,content:"TABLE RULES: use the native table with an ordered columns array, compact density, explicit pagination/pageSize for large data, and selection interaction when requested."},
        {id:"charts",include:settings.chartsRequired,content:"CHART RULES: category and measure references must be supplied aliases or fields produced by the selected dataset. Prefer semantic charts; keep labels and marks compact."},
        {id:"advanced-chart",include:advanced,content:"ADVANCED CHART: JSON-only safe ECharts presentation overrides are allowed; they may not replace semantic data bindings, functions, formatters, events, or unsafe options."},
        {id:"svg",include:svgRequested,content:`SVG VISUALS: Prefer type "svg" with approved structured elements (g, path, rect, circle, ellipse, line, polyline, polygon, text, tspan, defs, gradients, stop, clipPath, mask, marker, title, desc). Use literal, bind, template, scale, map, conditional, and state values. Prefer presets such as progress-fill, flow-dash, swim, pulse, draw-path, and fade-in. Include ariaLabel; stable IDs and accessible labels on interactive marks; use repeat with a bounded limit and keyField. Never emit JavaScript, event attributes, foreignObject, image/use, external URLs, external libraries, or path morphing. Respect reduced motion and stay below 500 elements and 20 animated elements. Use ECharts—not SVG—for standard analytical charts. svgMarkup is an advanced escape hatch and should be used only when the user explicitly asks for raw SVG.`},
        {id:"security",include:true,content:security},
        {id:"current-specification",include:improvement,content:`CURRENT DASHBOARD (return the complete updated specification; preserve unrelated functionality and IDs):\n${context.currentSpecification||"{}"}`},
        {id:"repair-diagnostics",include:repair,content:`STRUCTURED DIAGNOSTICS:\n${JSON.stringify(context.diagnostics??[],null,2)}`},
        {id:"change-package",include:settings.job==="redesign-section"||settings.job==="add-section",content:`Allowed operations: replace, insertBefore, insertAfter, appendChild, appendRoot. Return one strict {"kind":"hyperpbi-change","version":"1.0",...} object. ${settings.job==="redesign-section"?`Use operation replace and targetId ${context.selectedComponentId}; the replacement component must preserve that ID.`:context.insertionRootContainer?`Use operation appendRoot and containerPath ${context.insertionRootContainer}. Do not invent a targetId for a root destination.`:`Use targetId ${context.insertionTargetId} (type ${context.insertionTargetType??"unknown"}, JSON pointer ${context.insertionTargetPath??"unknown"}) and operation ${context.insertionPosition==="before"?"insertBefore":context.insertionPosition==="after"?"insertAfter":"appendChild"}.${context.insertionPosition==="inside"?` Use the exact descriptor-declared relative containerPath ${context.insertionContainerPath}.`:""}`} Do not return an unrelated full dashboard.`},
        {id:"selected-section",include:settings.job==="redesign-section",content:`Selected authoring node: ID ${context.selectedComponentId}; type ${context.selectedComponentType??"unknown"}; title ${context.selectedComponentTitle??"untitled"}; JSON pointer ${context.selectedComponentPath??"unknown"}.`},
        {id:"output-contract",include:true,content:output}
    ];
    const jobInstruction=improvement?"Improve the current schema 2.0 dashboard and return the complete updated specification with version \"2.0\". Preserve unrelated working sections.":repair?"Repair the invalid JSON using only the supplied diagnostics and return schema version \"2.0\" while preserving valid unrelated content.":settings.job==="add-section"?"Return one validated schema 2.0 section package with an explicit insertion target.":settings.job==="redesign-section"?"Return one schema 2.0 replacement component or section.":"Create one complete dashboard specification with version \"2.0\".";
    const header=`You are authoring an AI-first declarative HyperPBI dashboard. ${jobInstruction}\n\nUSER INTENT:\nGoal: ${settings.goal}\nAudience: ${settings.audience}\nDecisions supported: ${settings.decisions||"Not specified"}\nPrimary entity: ${settings.primaryEntity||"Infer only from supplied fields"}\nApplication type: ${settings.applicationType}\nLayout: ${settings.layoutPattern}\nImportant KPIs: ${settings.importantKpis||"Infer conservatively"}\nRequired sections: ${settings.requiredSections||settings.components.join(", ")}\nRequired filters: ${settings.requiredFilters||"None specified"}\nDevice priority: ${settings.devicePriority}\nViewport: ${context.width??"unknown"} × ${context.height??"unknown"}`;
    let prompt=[header,...modules.filter(module=>module.include).map(module=>`\n## ${module.id}\n${module.content}`)].join("\n");const warnings:string[]=[];const budget=context.budget??14000;const approximateTokens=Math.ceil(prompt.length/4);if(approximateTokens>budget)warnings.push(`Prompt is approximately ${approximateTokens} tokens, above the ${budget}-token budget.`);
    return{prompt,includedModules:modules.filter(item=>item.include).map(item=>item.id),excludedModules:modules.filter(item=>!item.include).map(item=>item.id),approximateTokens,warnings,fieldAliases:fields.map(field=>field.alias)};
}
