import { Component, ComponentChildren } from "preact";
export class ComponentErrorBoundary extends Component<{id:string;type:string;dataset?:string;developer:boolean;children:ComponentChildren},{error?:Error}>{state:{error?:Error}={};static getDerivedStateFromError(error:Error){return{error};}componentDidCatch(error:Error){this.setState({error});}render(){if(!this.state.error)return this.props.children;return <section class="hp-component-error" role="status"><strong>This section could not be displayed.</strong>{this.props.developer&&<details><summary>Developer diagnostics</summary><dl><dt>Component ID</dt><dd>{this.props.id}</dd><dt>Type</dt><dd>{this.props.type}</dd><dt>Data view</dt><dd>{this.props.dataset??"powerbi"}</dd><dt>Render exception</dt><dd>{this.state.error.message}</dd><dt>Suggested action</dt><dd>Review this component in the inspector or copy a focused repair prompt.</dd></dl></details>}</section>;}}
